import{_ as e,o as d,c as o,an as r}from"./chunks/framework.PNhEgmOx.js";const _=JSON.parse('{"title":"Environment variables","description":"","frontmatter":{},"headers":[],"relativePath":"config/environment.md","filePath":"config/environment.md","lastUpdated":null}'),a={name:"config/environment.md"};function i(n,t,c,s,l,h){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="Environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#Environment-variables" aria-label="Permalink to &quot;Environment variables {#Environment-variables}&quot;">​</a></h1><p>Run behavior belongs in the TOML configuration. The environment variables below are for paths, metadata, profiling and diagnostics; none of them changes results unless noted. <code>test/core/test_environment_variables.jl</code> checks that the package reads no others.</p><h2 id="Paths-and-metadata" tabindex="-1">Paths and metadata <a class="header-anchor" href="#Paths-and-metadata" aria-label="Permalink to &quot;Paths and metadata {#Paths-and-metadata}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Variable</th><th style="text-align:right;">Effect</th><th style="text-align:right;">Read in</th></tr></thead><tbody><tr><td style="text-align:right;"><code>ATMOSTRANSPORT_DATA_ROOT</code></td><td style="text-align:right;">Root of <code>$ATMOSTRANSPORT_DATA_ROOT</code> in configured paths (default <code>~/data/AtmosTransport</code>). Any other <code>$NAME</code> or <code>${NAME}</code> in a path expands to that variable.</td><td style="text-align:right;"><code>expand_data_path</code> (<code>src/AtmosTransport.jl</code>)</td></tr><tr><td style="text-align:right;"><code>ATMOSTR_REGRID_CACHE_DIR</code></td><td style="text-align:right;">Cache of conservative regridding weights for surface fluxes (default <code>~/.cache/AtmosTransport/cr_regridding</code>).</td><td style="text-align:right;"><code>src/Models/initial_conditions/surface_flux.jl</code></td></tr><tr><td style="text-align:right;"><code>ATMOSTR_SPECTRAL_CACHE_DIR</code></td><td style="text-align:right;">Default spectral-coefficient cache of the ERA5 preprocessor; <code>[cache] spectral_coefficients_dir</code> overrides it.</td><td style="text-align:right;"><code>src/Preprocessing/configuration.jl</code></td></tr><tr><td style="text-align:right;"><code>ATMOSTR_SCRATCH_DIR</code>, <code>ATMOSTR_TMPDIR</code>, <code>SCRATCH</code>, <code>TMPDIR</code>, <code>TEMP</code>, <code>TMP</code></td><td style="text-align:right;">Candidate directories, in this order, for extracting ERA5 surface archives.</td><td style="text-align:right;"><code>src/Preprocessing/era5_surface_reader.jl</code></td></tr><tr><td style="text-align:right;"><code>ATMOSTR_INSTITUTION</code></td><td style="text-align:right;"><code>institution</code> attribute of NetCDF snapshot and observation files.</td><td style="text-align:right;"><code>src/Output/netcdf_schema.jl</code>, <code>src/Output/observations/observation_netcdf.jl</code></td></tr><tr><td style="text-align:right;"><code>USER</code>, <code>USERNAME</code></td><td style="text-align:right;"><code>user</code> attribute of NetCDF snapshot files.</td><td style="text-align:right;"><code>src/Output/netcdf_schema.jl</code></td></tr><tr><td style="text-align:right;"><code>NO_COLOR</code>, <code>TERM</code></td><td style="text-align:right;">ANSI colors in the run summary only when <code>NO_COLOR</code> is unset or empty and <code>TERM</code> is set and not <code>dumb</code>.</td><td style="text-align:right;"><code>src/Models/runner/configuration.jl</code></td></tr></tbody></table><h2 id="Profiling-and-diagnostics" tabindex="-1">Profiling and diagnostics <a class="header-anchor" href="#Profiling-and-diagnostics" aria-label="Permalink to &quot;Profiling and diagnostics {#Profiling-and-diagnostics}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Variable</th><th style="text-align:right;">Effect</th><th style="text-align:right;">Read in</th></tr></thead><tbody><tr><td style="text-align:right;"><code>ATMOSTR_TIMERS</code>, <code>ATMOSTR_NVTX</code>, <code>ATMOSTR_ALLOC_TIMERS</code></td><td style="text-align:right;">Section timers, NVTX ranges, and allocation counts within the timers (<code>1</code>, <code>true</code>, <code>on</code> or <code>yes</code>; <code>ATMOSTR_ALLOC_TIMERS</code> only together with <code>ATMOSTR_TIMERS</code>).</td><td style="text-align:right;"><code>src/Diagnostics/SectionTimer.jl</code></td></tr><tr><td style="text-align:right;"><code>ATMOSTR_PROFILE_GPU</code></td><td style="text-align:right;">With timers on (<code>1</code>, <code>true</code>, <code>on</code> or <code>yes</code>): synchronize after each cubed-sphere sweep kernel and time the launch and the wait separately (slower).</td><td style="text-align:right;"><code>src/Operators/Advection/cs_sweep_common.jl</code></td></tr><tr><td style="text-align:right;"><code>ATMOSTR_ASSERT_CS_BINARY_CFL</code></td><td style="text-align:right;"><code>1</code>: recompute the cubed-sphere CFL subcycle count and stop if the binary&#39;s substep schedule asks for fewer (slower).</td><td style="text-align:right;"><code>src/Operators/Advection/CubedSphereStrang.jl</code></td></tr><tr><td style="text-align:right;"><code>ATMOSTR_DISABLE_PREFETCH</code></td><td style="text-align:right;"><code>1</code>: load each met window synchronously instead of prefetching the next one on a second thread.</td><td style="text-align:right;"><code>src/Models/driven_window_state.jl</code></td></tr><tr><td style="text-align:right;"><code>ATMOS_OMEGA_TIMING</code></td><td style="text-align:right;">Timing output of the GEOS OMEGA-consistent <code>cm</code> closure in the preprocessor.</td><td style="text-align:right;"><code>src/Preprocessing/transport_binary/cubed_sphere_geos.jl</code></td></tr><tr><td style="text-align:right;"><code>ERA5_N320_PROFILE</code></td><td style="text-align:right;"><code>1</code>: per-window timing of the ERA5 N320 preprocessor.</td><td style="text-align:right;"><code>src/Preprocessing/sources/era5_n320_window.jl</code>, <code>era5_n320_to_cs.jl</code></td></tr></tbody></table><h2 id="Preprocessing-switches" tabindex="-1">Preprocessing switches <a class="header-anchor" href="#Preprocessing-switches" aria-label="Permalink to &quot;Preprocessing switches {#Preprocessing-switches}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Variable</th><th style="text-align:right;">Effect</th><th style="text-align:right;">Read in</th></tr></thead><tbody><tr><td style="text-align:right;"><code>ATMOSTR_NO_WRITE_REPLAY_CHECK</code></td><td style="text-align:right;"><code>1</code>: skip the write-time replay-continuity gate of the preprocessor (diagnostic only). The binary records <code>write_replay_check = false</code>; the inspector marks it and the runtime warns when it opens it.</td><td style="text-align:right;"><code>write_replay_check_enabled</code> (<code>src/Preprocessing/configuration.jl</code>)</td></tr></tbody></table><h2 id="Deprecated" tabindex="-1">Deprecated <a class="header-anchor" href="#Deprecated" aria-label="Permalink to &quot;Deprecated {#Deprecated}&quot;">​</a></h2><p>These still work for one release and warn when used.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Variable</th><th style="text-align:right;">Replacement</th></tr></thead><tbody><tr><td style="text-align:right;"><code>ATMOSTR_FORCE_PER_SUBSTEP_PHYSICS</code> (<strong>changes results</strong>)</td><td style="text-align:right;"><code>[run] physics_cadence = &quot;substep&quot;</code></td></tr><tr><td style="text-align:right;"><code>ATMOSTR_REPLAY_CHECK</code></td><td style="text-align:right;"><code>[input] validate_replay = true</code></td></tr><tr><td style="text-align:right;"><code>ATMOSTR_ENABLE_HORIZONTAL_POISSON_BALANCE</code> (preprocessor, <strong>changes results</strong>)</td><td style="text-align:right;"><code>[numerics] balance_mode = &quot;per_layer&quot;</code></td></tr></tbody></table><p><code>ATMOSTR_NO_REPLAY_CHECK</code> was removed: it can no longer suppress a load-time replay check requested by <code>[input] validate_replay</code>, the driver&#39;s <code>validate_replay</code> keyword or the deprecated <code>ATMOSTR_REPLAY_CHECK</code>.</p><h2 id="Command-line-runner" tabindex="-1">Command-line runner <a class="header-anchor" href="#Command-line-runner" aria-label="Permalink to &quot;Command-line runner {#Command-line-runner}&quot;">​</a></h2><p><code>scripts/run_transport.jl</code> reads these before the package loads:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Variable</th><th style="text-align:right;">Effect</th></tr></thead><tbody><tr><td style="text-align:right;"><code>JULIA_NUM_THREADS</code></td><td style="text-align:right;">Thread count. When it is unset and Julia runs one thread, the runner restarts itself with two threads (also after an explicit <code>--threads=1</code>).</td></tr><tr><td style="text-align:right;"><code>ATMOSTR_NO_AUTO_THREADS</code></td><td style="text-align:right;"><code>1</code>: do not restart with two threads (needed to run with one thread).</td></tr><tr><td style="text-align:right;"><code>ATMOSTR_PROFILE_MODE</code></td><td style="text-align:right;"><code>full</code>: CUDA activity profile of the whole run. <code>window</code>: profile a window of the run and then <strong>end the process</strong>, so the run does not finish.</td></tr><tr><td style="text-align:right;"><code>ATMOSTR_PROFILE_WARMUP_SEC</code>, <code>ATMOSTR_PROFILE_DUR_SEC</code></td><td style="text-align:right;">Start (default 120 s) and length (default 60 s) of the <code>window</code> profile.</td></tr></tbody></table>',15)])])}const y=e(a,[["render",i]]);export{_ as __pageData,y as default};
